	return pcapint_filter(pc, BPF_MAXINSNS, p, wirelen, buflen);
}

int
bpf_validate(const struct bpf_insn *f, int len)
{
	// The implicit conversion of 'len' from signed to unsigned is fine.
	return pcapint_validate_filter(f, len);
